def ipa(word):
    if word in ipa_overrides:return ipa_overrides[word]
    sounds=[s for r in evidence[word] for s in r.get('sounds',[]) if s.get('ipa','').startswith('/') and not s.get('ipa','').startswith('/-')]
    for s in sounds:
        if 'Received-Pronunciation' in s.get('tags',[]):return s['ipa']
    if sounds:return sounds[0]['ipa']
    raise ValueError('Need IPA: '+word)
def P(*nodes): return [list(n) for n in nodes]
